    // Core objective: minimize gap, but prioritize tight fits for the upcoming item
    let mut score = (post * post) * 0.072;
    score -= 158.0 / (1.0 + (post * 0.42));

    if next_item_size > 0 {
        let n = next_item_size as f64;
