        let density_pressure = (open_bins_count as f64 / (total_items as f64 / 45.0)).clamp(0.2, 6.0);
        score += 108.0 + (progress * 145.0) + (fitting_bins_count as f64 * 32.0 * density_pressure * (1.05 - progress));
