    // Penalty for creating a "sliver" (fragmentation) that is unlikely to fit future items.
    // If post_residual is small but not zero, it's often a "dead" zone.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic logic: Favor filling bins to near-capacity (Best Fit-like behavior).
    // Penalize bins that would remain half-empty if we could pack them tighter.
    if post_residual > 40 && post_residual < 60 {
        score += 15.0;
    }

    // Lookahead logic: If the next item can fit into the remaining space, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // If this is the only bin that fits the current item, prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // If we are considering opening a new bin (bin_residual == bin_capacity),
    // apply a global cost to discourage it unless the existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we are late in the stream, penalize opening new bins more heavily.
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // Adjust score by the mean residual to encourage balancing bin utilization.
    // Bins with higher than average residual are preferred for small items.
    score += (post_residual as f64 - mean_residual) * 0.1;

    score
}

