    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Core objective: Minimize quadratic penalty of residual space with tuned gain
    let mut score = (post * post) * 0.086;
    score -= 230.0 / (1.0 + (post * 0.50));

    // Lookahead: Refined anticipation to prioritize bins that leave space for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post > 0.0 && post < n {
            score += (n - post) * 58.0; // Strong penalty for stranding next item
        } else if post >= n {
            score -= 72.0 * (1.0 - ((post - n) / capacity).powf(0.88)) * (1.1 - progress * 0.45);
        }
    }

    if is_new_bin {
        // Adaptive threshold for opening new bins: scale pressure with progress to prevent early fragmentation
        let density_pressure = (open_bins_count as f64 / (total_items as f64 / 80.0)).clamp(0.12, 8.5);
        score += 175.0 + (progress * 235.0) + (fitting_bins_count as f64 * 55.0 * density_pressure * (1.25 - progress));
    } else {
        let utilization = 1.0 - (post / capacity);
        let mean_utilization = 1.0 - (mean_residual / capacity);

        // Variance control: tighten the distribution around the mean residual
        score += (utilization - mean_utilization).abs() * 180.0;

        // Refined "Perfect Fit" incentive: favoring bins leaving < 15% space
        let threshold = capacity * 0.15;
        if post < threshold {
            score -= 205.0 * (1.0 - (post / threshold).powf(0.70));
        }

        // Anti-starvation: penalize low utilization bins
        if utilization < 0.50 {
            score += 160.0 * (1.0 - progress.powf(0.6));
        }

        // Deep compaction: extra reward for near-full bins
        if post < (capacity * 0.03) {
            score -= 185.0;
        }

        // Dynamic Bin Count Pressure: penalize high fragmentation
        if open_bins_count > (total_items / 110) {
            score += (post / capacity) * 95.0;
        }

        // Efficiency constraint: target a tighter bound relative to the running mean
        if post > mean_residual * 1.10 {
            score += 80.0 * (post / (mean_residual + 0.1));
        }

        // Micro-residual cleanup: prioritize filling small gaps
        if post > 0.0 && post < 10.0 {
            score -= 78.0;
        }

        // Early stage stabilization
        if progress < 0.28 && post > capacity * 0.62 {
            score -= 110.0;
        }

        // Consolidation Logic: aggressive penalty for "dead-zone" residuals
        if post > mean_residual && post < (mean_residual * 1.38) {
            score += 48.0 * (post / mean_residual);
        }

        // Bonus for creating high-density clusters
        if post < (mean_residual * 0.48) {
            score -= 52.0;
        }
    }

    score
}

