    // We prioritize bins that leave the smallest residual (Best Fit).
    // We penalize new bins based on the progress of the stream to delay opening new bins early.
    // We use next_item_size to penalize bins that leave a residual smaller than the next item if possible.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins heavily early on
    if is_new_bin {
        let progress = step_index as f64 / total_items as f64;
        score += 100.0 * (1.0 - progress);

        // If there are fitting bins, heavily penalize opening a new one unless it's a perfect fit
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 2. Lookahead: Avoid creating 'dead' space that cannot fit the next item
    if next_item_size > 0 && post_residual < next_item_size {
        // Only penalize if the residual is not zero (which is perfect)
        if post_residual > 0 {
            score += 25.0;
        }
    }

    // 3. Global state: If mean residual is high, we have many empty spaces. 
    // Penalize new bins if mean_residual is large (suggests we should fill existing ones).
    if is_new_bin {
        score += mean_residual * 0.5;
    }

    // 4. Prefer bins that are already "tight" if we aren't opening a new one
    if !is_new_bin {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Adjusted quadratic base cost to favor tighter packing of remaining space
    let mut score = (post * post) * 0.089;
    score -= 218.0 / (1.0 + (post * 0.50));

    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post > 0.0 && post < n {
            // Strong penalty for creating a gap too small for the next item
            score += (n - post) * 58.0;
        } else if post >= n {
            // Reward bins that leave space for the next item based on progress
            score -= 70.0 * (1.0 - ((post - n) / capacity).powf(0.88)) * (1.1 - progress * 0.38);
        }
    }

    if is_new_bin {
        let density_pressure = (open_bins_count as f64 / (total_items as f64 / 70.0)).clamp(0.12, 8.0);
        // Calibrated cost of opening new bins based on current packing density
        score += 172.0 + (progress * 235.0) + (fitting_bins_count as f64 * 44.0 * density_pressure * (1.28 - progress));
    } else {
        let utilization = 1.0 - (post / capacity);
        let mean_utilization = 1.0 - (mean_residual / capacity);

        // Deviation from mean behavior penalty
        score += (utilization - mean_utilization).abs() * 168.0;

        let threshold = capacity * 0.16;
        if post < threshold {
            score -= 188.0 * (1.0 - (post / threshold).powf(0.75));
        }

        // Penalty for low utilization that doesn't improve over time
        if utilization < 0.50 {
            score += 148.0 * (1.0 - progress.powf(0.53));
        }

        if post < (capacity * 0.045) {
            score -= 162.0;
        }

        // Dynamic penalty for excessive open bins
        if open_bins_count > (total_items / 108) {
            score += (post / capacity) * 88.0;
        }

        // Prevent straggler bins with high residual
        if post > mean_residual * 1.14 {
            score += 68.0 * (post / (mean_residual + 0.18));
        }

        // Localized reward for small residual fragments
        if post > 0.0 && post < 11.5 {
            score -= 70.0;
        }

        // Early game consolidation focus
        if progress < 0.32 && post > capacity * 0.64 {
            score -= 112.0;
        }

        // Targeted penalty for mid-range waste that blocks small item fitting
        if post > mean_residual && post < (mean_residual * 1.45) {
            score += 38.0 * (post / (mean_residual + 0.5));
        }

        // Encourage near-perfect fits
        if post < 2.0 {
            score -= 98.0 * (1.0 - progress * 0.22);
        }

        // Anti-fragmentation: prioritize bins that are closer to the mean_residual
        if post < mean_residual * 0.5 {
            score -= 42.0 * (1.0 - (post / mean_residual));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the new bin option (bin_residual == bin_capacity) increasingly as the stream progresses
    // to force packing into existing bins late in the game.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        20.0 + (progress * 50.0) 
    } else { 
        0.0 
    };

    // Calculate a "tightness" factor: we prefer bins where the post_residual is small (Best Fit),
    // but we penalize bins that leave very small, unusable gaps (e.g., < 10) if they are 
    // likely to remain empty for the rest of the stream.
    // The non-linear term (post^1.5) discourages leaving moderate gaps.
    let tightness_score = post.powf(1.5);

    // Lookahead coupling: if the next item is large and this bin can't accommodate it,
    // we penalize the current placement to save space for the next item.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        15.0 * (next_item_size as f64 / 100.0)
    } else {
        0.0
    };

    // Diversity penalty: avoid piling everything into one bin if the mean residual is already low.
    // This balances the load across open bins early on.
    let load_balance = if open_bins_count > 1 {
        (mean_residual - post) * (1.0 - progress)
    } else {
        0.0
    };

    let score = tightness_score + new_bin_penalty + lookahead_penalty + load_balance;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
