    if is_new_bin {
        // Dynamic threshold for opening new bins: only open if existing bins are saturated
        let density_pressure = (open_bins_count as f64 / (total_items as f64 / 72.0)).clamp(0.12, 8.0);
        score += 175.0 + (progress * 210.0) + (fitting_bins_count as f64 * 45.0 * density_pressure * (1.20 - progress));
    } else {
        let utilization = 1.0 - (post / capacity);
        let mean_utilization = 1.0 - (mean_residual / capacity);

        // Penalize variance from the mean to promote uniform bin filling
        score += (utilization - mean_utilization).abs() * 172.0;

        // Reward filling small gaps
        if post < (capacity * 0.18) {
            score -= 195.0 * (1.0 - (post / (capacity * 0.18)).powf(0.75));
        }

        // Discourage opening too many bins early on
        if utilization < 0.48 {
            score += 155.0 * (1.0 - progress.powf(0.60));
        }

        // Aggressive consolidation for near-perfect fits
        if post < 8.0 {
            score -= 168.0;
        }

        // Adaptive thresholding based on remaining stream length
        if open_bins_count > (total_items / 98) {
            score += (post / capacity) * 92.0;
        }

        // Penalty for leaving "dead space" that is slightly larger than the mean residual
        if post > mean_residual && post < (mean_residual * 1.55) {
            score += 42.0 * (post / (mean_residual + 1.0));
        }

        // Mid-game optimization: favor packing into bins with lower residuals if progress is high
        if progress > 0.4 && post < (mean_residual * 0.6) {
