    let post = post_residual as f64;
    let capacity = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Core quadratic cost for residual space, tuned for tighter packing
    let mut score = (post * post) * 0.086;
    score -= 218.0 / (1.0 + (post * 0.50));

    // Lookahead: prioritize bins that leave space for the next item, or reward efficient fits
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post > 0.0 && post < n {
            score += (n - post) * 55.0;
        } else if post >= n {
            score -= 70.0 * (1.0 - ((post - n) / capacity).powf(0.88)) * (1.1 - progress * 0.38);
