    if is_new_bin {
        // Dynamic threshold for opening new bins based on phase of packing
        let density_pressure = (open_bins_count as f64 / (total_items as f64 / 70.0)).clamp(0.14, 7.8);
        score += 172.0 + (progress * 235.0) + (fitting_bins_count as f64 * 45.0 * density_pressure * (1.28 - progress));
    } else {
        let utilization = 1.0 - (post / capacity);
        let mean_utilization = 1.0 - (mean_residual / capacity);

        // Penalize variance from mean usage to encourage uniform bin filling
        score += (utilization - mean_utilization).abs() * 168.0;

        // Aggressive reward for creating small, tight residuals
        let threshold = capacity * 0.16;
        if post < threshold {
            score -= 190.0 * (1.0 - (post / threshold).powf(0.75));
        }

        // Late-game compaction: penalize low-utilization bins
        if utilization < 0.50 {
            score += 148.0 * (1.0 - progress.powf(0.53));
        }

        // Prevent excessive open bins
        if open_bins_count > (total_items / 108) {
            score += (post / capacity) * 88.0;
        }

        // Penalty for bins that drift far from the mean residual
        if post > mean_residual * 1.14 {
            score += 68.0 * (post / (mean_residual + 0.18));
        }

        // Small item consolidation: reward placing small items in tight spots
        if post > 0.0 && post < 11.5 {
            score -= 70.0;
        }

        // Early-game optimization: favor fuller bins
        if progress < 0.32 && post > capacity * 0.63 {
            score -= 112.0;
        }

        // Mid-range waste mitigation: avoid leaving bins "half-full" relative to mean
        if post > mean_residual && post < (mean_residual * 1.45) {
            score += 38.0 * (post / (mean_residual + 0.5));
        }

        // Perfect fit reward
        if post < 1.5 {
